package com.example.wear.watchface

import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.content.IntentFilter
import android.graphics.*
import android.text.format.DateFormat
import android.util.Log
import androidx.wear.watchface.CanvasType
import androidx.wear.watchface.ComplicationSlotsManager
import androidx.wear.watchface.WatchFace
import androidx.wear.watchface.WatchFaceService
import androidx.wear.watchface.WatchFaceType
import androidx.wear.watchface.WatchState
import androidx.wear.watchface.style.CurrentUserStyleRepository
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.launch
import java.time.ZonedDateTime
import java.io.File
import org.w3c.dom.Document
import org.w3c.dom.Element
import javax.xml.parsers.DocumentBuilderFactory

class CustomWatchFaceService : WatchFaceService() {

    companion object {
        private const val TAG = "CustomWatchFaceService"
    }

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Main.immediate)

    override suspend fun createWatchFace(
        surfaceHolder: android.view.SurfaceHolder,
        watchState: WatchState,
        complicationSlotsManager: ComplicationSlotsManager,
        currentUserStyleRepository: CurrentUserStyleRepository
    ): WatchFace {
        Log.d(TAG, "Creating custom watch face")

        val renderer = CustomWatchFaceRenderer(
            context = applicationContext,
            surfaceHolder = surfaceHolder,
            watchState = watchState,
            currentUserStyleRepository = currentUserStyleRepository,
            canvasType = CanvasType.HARDWARE
        )

        return WatchFace(
            watchFaceType = WatchFaceType.ANALOG,
            renderer = renderer
        )
    }

    override fun onDestroy() {
        super.onDestroy()
        scope.cancel()
    }
}

class CustomWatchFaceRenderer(
    private val context: Context,
    surfaceHolder: android.view.SurfaceHolder,
    watchState: WatchState,
    private val currentUserStyleRepository: CurrentUserStyleRepository,
    canvasType: CanvasType
) : androidx.wear.watchface.Renderer.CanvasRenderer(
    surfaceHolder,
    currentUserStyleRepository,
    watchState,
    canvasType,
    FRAME_PERIOD_MS_DEFAULT
) {

    companion object {
        private const val TAG = "CustomWatchFaceRenderer"
        private const val FRAME_PERIOD_MS_DEFAULT = 16L // 60 FPS
    }

    // Paint objects for drawing - will be updated based on watch face XML
    private var backgroundPaint = Paint().apply {
        color = Color.BLACK
        isAntiAlias = true
    }

    private var hourHandPaint = Paint().apply {
        color = Color.WHITE
        strokeWidth = 8f
        strokeCap = Paint.Cap.ROUND
        isAntiAlias = true
        style = Paint.Style.STROKE
    }

    private var minuteHandPaint = Paint().apply {
        color = Color.WHITE
        strokeWidth = 6f
        strokeCap = Paint.Cap.ROUND
        isAntiAlias = true
        style = Paint.Style.STROKE
    }

    private var secondHandPaint = Paint().apply {
        color = Color.RED
        strokeWidth = 2f
        strokeCap = Paint.Cap.ROUND
        isAntiAlias = true
        style = Paint.Style.STROKE
    }

    private var centerDotPaint = Paint().apply {
        color = Color.WHITE
        isAntiAlias = true
        style = Paint.Style.FILL
    }

    private var hourMarkPaint = Paint().apply {
        color = Color.WHITE
        strokeWidth = 4f
        isAntiAlias = true
        style = Paint.Style.STROKE
    }

    // Current watch face resources
    private var currentWatchFaceResources: WatchFaceResources? = null
    private var backgroundBitmap: Bitmap? = null
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Main.immediate)

    // Watch face configuration from XML
    private var watchFaceConfig: WatchFaceConfig? = null

    // BroadcastReceiver to listen for watch face changes
    private val watchFaceChangeReceiver = object : BroadcastReceiver() {
        override fun onReceive(context: Context?, intent: Intent?) {
            val watchFaceId = intent?.getStringExtra("watch_face_id")
            Log.d(TAG, "Received watch face change broadcast: $watchFaceId")

            if (watchFaceId != null) {
                loadWatchFaceById(watchFaceId)
            } else {
                loadDefaultWatchFace()
            }

            // Force redraw
            invalidate()
        }
    }

    init {
        // Register receiver for watch face changes
        val filter = IntentFilter("com.example.wear.WATCH_FACE_CHANGED")
        context.registerReceiver(watchFaceChangeReceiver, filter)

        loadCurrentWatchFace()

        // Ensure default watch face exists
        scope.launch {
            try {
                val defaultProvider = DefaultWatchFaceProvider(context)
                defaultProvider.ensureDefaultWatchFaceExists()
            } catch (e: Exception) {
                Log.e(TAG, "Failed to ensure default watch face exists", e)
            }
        }
    }

    private fun loadCurrentWatchFace() {
        try {
            val watchFaceManager = WatchFaceManager(context)
            val currentWatchFace = watchFaceManager.getCurrentWatchFace()

            if (currentWatchFace != null) {
                Log.d(TAG, "Loading current watch face: ${currentWatchFace.name}")
                loadWatchFaceById(currentWatchFace.id)
            } else {
                Log.d(TAG, "No current watch face set, using default")
                loadDefaultWatchFace()
            }
        } catch (e: Exception) {
            Log.e(TAG, "Failed to load current watch face, falling back to default", e)
            loadDefaultWatchFace()
        }
    }

    private fun loadDefaultWatchFace() {
        Log.d(TAG, "Loading default watch face")
        // Reset to default styling
        backgroundBitmap = null
        watchFaceConfig = null
        resetToDefaultColors()
    }

    private fun loadWatchFaceById(watchFaceId: String) {
        try {
            val watchFaceDir = File(context.filesDir, "extracted_watchfaces/$watchFaceId")
            if (watchFaceDir.exists()) {
                loadWatchFaceFromDirectory(watchFaceDir)
            } else {
                Log.w(TAG, "Watch face directory not found for ID: $watchFaceId, using default")
                loadDefaultWatchFace()
            }
        } catch (e: Exception) {
            Log.e(TAG, "Failed to load watch face by ID: $watchFaceId", e)
            loadDefaultWatchFace()
        }
    }

    private fun loadWatchFaceFromDirectory(watchFaceDir: File) {
        try {
            Log.d(TAG, "Loading watch face from directory: ${watchFaceDir.name}")

            // Load background image if available
            val backgroundFile = File(watchFaceDir, "resources/images/background.png")
                .takeIf { it.exists() }
                ?: File(watchFaceDir, "resources/images/background.jpg")
                    .takeIf { it.exists() }

            backgroundBitmap = backgroundFile?.let { file ->
                BitmapFactory.decodeFile(file.absolutePath)?.let { bitmap ->
                    Log.d(TAG, "Loaded background image: ${file.name}")
                    bitmap
                }
            }

            // Parse watchface.xml for styling configuration
            val watchfaceXmlFile = File(watchFaceDir, "watchface.xml")
            if (watchfaceXmlFile.exists()) {
                val xmlContent = watchfaceXmlFile.readText()
                Log.d(TAG, "Found watchface.xml: ${xmlContent.length} characters")
                parseWatchFaceXml(watchfaceXmlFile)
            } else {
                Log.d(TAG, "No watchface.xml found, using default styling")
                watchFaceConfig = null
            }

            Log.d(TAG, "Successfully loaded watch face from directory")

        } catch (e: Exception) {
            Log.e(TAG, "Failed to load watch face resources", e)
            loadDefaultWatchFace()
        }
    }

    private fun parseWatchFaceXml(xmlFile: File) {
        try {
            val dbFactory = DocumentBuilderFactory.newInstance()
            val dBuilder = dbFactory.newDocumentBuilder()
            val doc: Document = dBuilder.parse(xmlFile)
            doc.documentElement.normalize()

            Log.d(TAG, "Parsing watchface.xml")

            // Extract basic configuration
            val watchFaceElement = doc.documentElement
            val width = watchFaceElement.getAttribute("width").toIntOrNull() ?: 450
            val height = watchFaceElement.getAttribute("height").toIntOrNull() ?: 450

            watchFaceConfig = WatchFaceConfig(
                width = width,
                height = height
            )

            // Parse color configurations if available
            parseColorConfiguration(doc)

            // Parse scene styling
            parseSceneConfiguration(doc)

            Log.d(TAG, "Successfully parsed watchface.xml")

        } catch (e: Exception) {
            Log.e(TAG, "Failed to parse watchface.xml", e)
            watchFaceConfig = null
        }
    }

    private fun parseColorConfiguration(doc: Document) {
        try {
            val colorConfigs = doc.getElementsByTagName("ColorConfiguration")
            if (colorConfigs.length > 0) {
                val colorConfig = colorConfigs.item(0) as Element
                val colorOptions = colorConfig.getElementsByTagName("ColorOption")

                if (colorOptions.length > 0) {
                    // Use first color option as default
                    val firstOption = colorOptions.item(0) as Element
                    val colors = firstOption.getAttribute("colors").split(" ")

                    if (colors.size >= 5) {
                        // Apply colors to paint objects
                        try {
                            hourHandPaint.color = Color.parseColor(colors[1])
                            minuteHandPaint.color = Color.parseColor(colors[1])
                            secondHandPaint.color = Color.parseColor(colors[2])
                            hourMarkPaint.color = Color.parseColor(colors[0])
                            centerDotPaint.color = Color.parseColor(colors[0])
                            backgroundPaint.color = Color.parseColor(colors[3])

                            Log.d(TAG, "Applied color configuration from XML")
                        } catch (e: Exception) {
                            Log.e(TAG, "Failed to parse colors", e)
                        }
                    }
                }
            }
        } catch (e: Exception) {
            Log.e(TAG, "Failed to parse color configuration", e)
        }
    }

    private fun parseSceneConfiguration(doc: Document) {
        try {
            val scenes = doc.getElementsByTagName("Scene")
            if (scenes.length > 0) {
                val scene = scenes.item(0) as Element
                val bgColor = scene.getAttribute("backgroundColor")

                if (bgColor.isNotEmpty() && bgColor.contains("#")) {
                    try {
                        backgroundPaint.color = Color.parseColor(bgColor.replace("[CONFIGURATION.themeColor.3]", "#000000"))
                        Log.d(TAG, "Applied scene background color")
                    } catch (e: Exception) {
                        Log.e(TAG, "Failed to parse scene background color", e)
                    }
                }
            }
        } catch (e: Exception) {
            Log.e(TAG, "Failed to parse scene configuration", e)
        }
    }

    private fun resetToDefaultColors() {
        hourHandPaint.color = Color.WHITE
        minuteHandPaint.color = Color.WHITE
        secondHandPaint.color = Color.RED
        hourMarkPaint.color = Color.WHITE
        centerDotPaint.color = Color.WHITE
        backgroundPaint.color = Color.BLACK
    }

    override fun render(canvas: Canvas, bounds: Rect, zonedDateTime: ZonedDateTime) {
        val centerX = bounds.exactCenterX()
        val centerY = bounds.exactCenterY()
        val radius = minOf(centerX, centerY) * 0.9f

        // Draw background
        if (backgroundBitmap != null) {
            val scaledBitmap = Bitmap.createScaledBitmap(
                backgroundBitmap!!,
                bounds.width(),
                bounds.height(),
                true
            )
            canvas.drawBitmap(scaledBitmap, 0f, 0f, null)
        } else {
            // Draw default background
            canvas.drawRect(bounds, backgroundPaint)
        }

        // Draw hour marks
        drawHourMarks(canvas, centerX, centerY, radius)

        // Calculate time
        val hour = zonedDateTime.hour % 12
        val minute = zonedDateTime.minute
        val second = zonedDateTime.second

        // Calculate angles (12 o'clock is 0 degrees)
        val hourAngle = (hour * 30f) + (minute * 0.5f) - 90f // 30 degrees per hour
        val minuteAngle = (minute * 6f) - 90f // 6 degrees per minute
        val secondAngle = (second * 6f) - 90f // 6 degrees per second

        // Draw hands
        drawHand(canvas, centerX, centerY, hourAngle, radius * 0.5f, hourHandPaint)
        drawHand(canvas, centerX, centerY, minuteAngle, radius * 0.7f, minuteHandPaint)

        // Only draw second hand in active mode
        if (!renderParameters.watchFaceLayers.contains(androidx.wear.watchface.WatchFaceLayer.BASE)) {
            drawHand(canvas, centerX, centerY, secondAngle, radius * 0.8f, secondHandPaint)
        }

        // Draw center dot
        canvas.drawCircle(centerX, centerY, 8f, centerDotPaint)
    }

    private fun drawHourMarks(canvas: Canvas, centerX: Float, centerY: Float, radius: Float) {
        val outerRadius = radius
        val innerRadius = radius * 0.9f

        for (i in 0 until 12) {
            val angle = Math.toRadians((i * 30 - 90).toDouble())
            val startX = centerX + (innerRadius * Math.cos(angle)).toFloat()
            val startY = centerY + (innerRadius * Math.sin(angle)).toFloat()
            val endX = centerX + (outerRadius * Math.cos(angle)).toFloat()
            val endY = centerY + (outerRadius * Math.sin(angle)).toFloat()

            canvas.drawLine(startX, startY, endX, endY, hourMarkPaint)
        }
    }

    private fun drawHand(
        canvas: Canvas,
        centerX: Float,
        centerY: Float,
        angle: Float,
        length: Float,
        paint: Paint
    ) {
        val angleRadians = Math.toRadians(angle.toDouble())
        val endX = centerX + (length * Math.cos(angleRadians)).toFloat()
        val endY = centerY + (length * Math.sin(angleRadians)).toFloat()

        canvas.drawLine(centerX, centerY, endX, endY, paint)
    }

    override fun renderHighlightLayer(canvas: Canvas, bounds: Rect, zonedDateTime: ZonedDateTime) {
        // Optional: Add highlight effects here
    }

    /**
     * Load a new watch face from resources
     */
    fun loadNewWatchFace(watchFaceResources: WatchFaceResources) {
        Log.d(TAG, "Loading new watch face: ${watchFaceResources.manifest.name}")
        currentWatchFaceResources = watchFaceResources

        // Load background image from the new watch face
        val backgroundFile = File(watchFaceResources.imagesDir, "background.png")
            .takeIf { it.exists() }
            ?: File(watchFaceResources.imagesDir, "background.jpg")
                .takeIf { it.exists() }

        backgroundBitmap = backgroundFile?.let { file ->
            BitmapFactory.decodeFile(file.absolutePath)?.also {
                Log.d(TAG, "Loaded new background image")
            }
        }

        // Parse and apply watchface.xml configurations
        currentWatchFaceResources?.watchfaceXml?.let { xml ->
            Log.d(TAG, "Applying watchface.xml configuration")
            // TODO: Parse XML string and update paint objects, layouts, etc.
        }

        // Force redraw
        invalidate()
    }

    // Clean up receiver when renderer is destroyed
    protected fun finalize() {
        try {
            context.unregisterReceiver(watchFaceChangeReceiver)
        } catch (e: Exception) {
            Log.w(TAG, "Failed to unregister receiver in finalize", e)
        }
    }
}

// Data class for watch face configuration
data class WatchFaceConfig(
    val width: Int,
    val height: Int,
    val backgroundColor: Int = Color.BLACK,
    val hourHandColor: Int = Color.WHITE,
    val minuteHandColor: Int = Color.WHITE,
    val secondHandColor: Int = Color.RED
)

package com.example.wear.watchface

import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.content.IntentFilter
import android.graphics.*
import android.service.wallpaper.WallpaperService
import android.util.Log
import android.view.SurfaceHolder
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.launch
import java.io.File
import java.util.Calendar
import org.w3c.dom.Document
import org.w3c.dom.Element
import javax.xml.parsers.DocumentBuilderFactory

class CustomWatchFaceService : WallpaperService() {

    companion object {
        private const val TAG = "CustomWatchFaceService"
    }

    override fun onCreateEngine(): Engine {
        return CustomWatchFaceEngine()
    }

    inner class CustomWatchFaceEngine : Engine() {

        private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Main.immediate)

        // Paint objects for drawing - will be updated based on watch face XML
        private var backgroundPaint = Paint().apply {
            color = Color.BLACK
            isAntiAlias = true
        }

        private var hourHandPaint = Paint().apply {
            color = Color.WHITE
            strokeWidth = 8f
            strokeCap = Paint.Cap.ROUND
            isAntiAlias = true
            style = Paint.Style.STROKE
        }

        private var minuteHandPaint = Paint().apply {
            color = Color.WHITE
            strokeWidth = 6f
            strokeCap = Paint.Cap.ROUND
            isAntiAlias = true
            style = Paint.Style.STROKE
        }

        private var secondHandPaint = Paint().apply {
            color = Color.RED
            strokeWidth = 2f
            strokeCap = Paint.Cap.ROUND
            isAntiAlias = true
            style = Paint.Style.STROKE
        }

        private var centerDotPaint = Paint().apply {
            color = Color.WHITE
            isAntiAlias = true
            style = Paint.Style.FILL
        }

        private var hourMarkPaint = Paint().apply {
            color = Color.WHITE
            strokeWidth = 4f
            isAntiAlias = true
            style = Paint.Style.STROKE
        }

        // Current watch face resources
        private var backgroundBitmap: Bitmap? = null
        private var watchFaceConfig: WatchFaceConfig? = null

        // BroadcastReceiver to listen for watch face changes
        private val watchFaceChangeReceiver = object : BroadcastReceiver() {
            override fun onReceive(context: Context?, intent: Intent?) {
                val watchFaceId = intent?.getStringExtra("watch_face_id")
                Log.d(TAG, "Received watch face change broadcast: $watchFaceId")

                if (watchFaceId != null) {
                    loadWatchFaceById(watchFaceId)
                } else {
                    loadDefaultWatchFace()
                }

                // Force redraw
                draw()
            }
        }

        override fun onCreate(surfaceHolder: SurfaceHolder) {
            super.onCreate(surfaceHolder)

            // Register receiver for watch face changes
            val filter = IntentFilter("com.example.wear.WATCH_FACE_CHANGED")
            applicationContext.registerReceiver(watchFaceChangeReceiver, filter)

            loadCurrentWatchFace()

            // Ensure default watch face exists
            scope.launch {
                try {
                    val defaultProvider = DefaultWatchFaceProvider(applicationContext)
                    defaultProvider.ensureDefaultWatchFaceExists()
                } catch (e: Exception) {
                    Log.e(TAG, "Failed to ensure default watch face exists", e)
                }
            }
        }

        override fun onDestroy() {
            super.onDestroy()
            try {
                applicationContext.unregisterReceiver(watchFaceChangeReceiver)
            } catch (e: Exception) {
                Log.w(TAG, "Failed to unregister receiver", e)
            }
            scope.cancel()
        }

        override fun onDraw(canvas: Canvas) {
            super.onDraw(canvas)

            val bounds = Rect(0, 0, canvas.width, canvas.height)
            val centerX = bounds.exactCenterX()
            val centerY = bounds.exactCenterY()
            val radius = minOf(centerX, centerY) * 0.9f

            // Draw background
            if (backgroundBitmap != null) {
                val scaledBitmap = Bitmap.createScaledBitmap(
                    backgroundBitmap!!,
                    bounds.width(),
                    bounds.height(),
                    true
                )
                canvas.drawBitmap(scaledBitmap, 0f, 0f, null)
            } else {
                // Draw default background
                canvas.drawRect(bounds, backgroundPaint)
            }

            // Draw hour marks
            drawHourMarks(canvas, centerX, centerY, radius)

            // Get current time
            val calendar = Calendar.getInstance()
            val hour = calendar.get(Calendar.HOUR) % 12
            val minute = calendar.get(Calendar.MINUTE)
            val second = calendar.get(Calendar.SECOND)

            // Calculate angles (12 o'clock is 0 degrees)
            val hourAngle = (hour * 30f) + (minute * 0.5f) - 90f // 30 degrees per hour
            val minuteAngle = (minute * 6f) - 90f // 6 degrees per minute
            val secondAngle = (second * 6f) - 90f // 6 degrees per second

            // Draw hands
            drawHand(canvas, centerX, centerY, hourAngle, radius * 0.5f, hourHandPaint)
            drawHand(canvas, centerX, centerY, minuteAngle, radius * 0.7f, minuteHandPaint)
            drawHand(canvas, centerX, centerY, secondAngle, radius * 0.8f, secondHandPaint)

            // Draw center dot
            canvas.drawCircle(centerX, centerY, 8f, centerDotPaint)
        }

        private fun loadCurrentWatchFace() {
            try {
                val watchFaceManager = WatchFaceManager(applicationContext)
                val currentWatchFace = watchFaceManager.getCurrentWatchFace()

                if (currentWatchFace != null) {
                    Log.d(TAG, "Loading current watch face: ${currentWatchFace.name}")
                    loadWatchFaceById(currentWatchFace.id)
                } else {
                    Log.d(TAG, "No current watch face set, using default")
                    loadDefaultWatchFace()
                }
            } catch (e: Exception) {
                Log.e(TAG, "Failed to load current watch face, falling back to default", e)
                loadDefaultWatchFace()
            }
        }

        private fun loadDefaultWatchFace() {
            Log.d(TAG, "Loading default watch face")
            // Reset to default styling
            backgroundBitmap = null
            watchFaceConfig = null
            resetToDefaultColors()
        }

        private fun loadWatchFaceById(watchFaceId: String) {
            try {
                val watchFaceDir = File(applicationContext.filesDir, "extracted_watchfaces/$watchFaceId")
                if (watchFaceDir.exists()) {
                    loadWatchFaceFromDirectory(watchFaceDir)
                } else {
                    Log.w(TAG, "Watch face directory not found for ID: $watchFaceId, using default")
                    loadDefaultWatchFace()
                }
            } catch (e: Exception) {
                Log.e(TAG, "Failed to load watch face by ID: $watchFaceId", e)
                loadDefaultWatchFace()
            }
        }

        private fun loadWatchFaceFromDirectory(watchFaceDir: File) {
            try {
                Log.d(TAG, "Loading watch face from directory: ${watchFaceDir.name}")

                // Load background image if available
                val backgroundFile = File(watchFaceDir, "resources/images/background.png")
                    .takeIf { it.exists() }
                    ?: File(watchFaceDir, "resources/images/background.jpg")
                        .takeIf { it.exists() }

                backgroundBitmap = backgroundFile?.let { file ->
                    BitmapFactory.decodeFile(file.absolutePath)?.let { bitmap ->
                        Log.d(TAG, "Loaded background image: ${file.name}")
                        bitmap
                    }
                }

                // Parse watchface.xml for styling configuration
                val watchfaceXmlFile = File(watchFaceDir, "watchface.xml")
                if (watchfaceXmlFile.exists()) {
                    val xmlContent = watchfaceXmlFile.readText()
                    Log.d(TAG, "Found watchface.xml: ${xmlContent.length} characters")
                    parseWatchFaceXml(watchfaceXmlFile)
                } else {
                    Log.d(TAG, "No watchface.xml found, using default styling")
                    watchFaceConfig = null
                }

                Log.d(TAG, "Successfully loaded watch face from directory")

            } catch (e: Exception) {
                Log.e(TAG, "Failed to load watch face resources", e)
                loadDefaultWatchFace()
            }
        }

        private fun parseWatchFaceXml(xmlFile: File) {
            try {
                val dbFactory = DocumentBuilderFactory.newInstance()
                val dBuilder = dbFactory.newDocumentBuilder()
                val doc: Document = dBuilder.parse(xmlFile)
                doc.documentElement.normalize()

                Log.d(TAG, "Parsing watchface.xml")

                // Extract basic configuration
                val watchFaceElement = doc.documentElement
                val width = watchFaceElement.getAttribute("width").toIntOrNull() ?: 450
                val height = watchFaceElement.getAttribute("height").toIntOrNull() ?: 450

                watchFaceConfig = WatchFaceConfig(
                    width = width,
                    height = height
                )

                // Parse color configurations if available
                parseColorConfiguration(doc)

                // Parse scene styling
                parseSceneConfiguration(doc)

                Log.d(TAG, "Successfully parsed watchface.xml")

            } catch (e: Exception) {
                Log.e(TAG, "Failed to parse watchface.xml", e)
                watchFaceConfig = null
            }
        }

        private fun parseColorConfiguration(doc: Document) {
            try {
                val colorConfigs = doc.getElementsByTagName("ColorConfiguration")
                if (colorConfigs.length > 0) {
                    val colorConfig = colorConfigs.item(0) as Element
                    val colorOptions = colorConfig.getElementsByTagName("ColorOption")

                    if (colorOptions.length > 0) {
                        // Use first color option as default
                        val firstOption = colorOptions.item(0) as Element
                        val colors = firstOption.getAttribute("colors").split(" ")

                        if (colors.size >= 5) {
                            // Apply colors to paint objects
                            try {
                                hourHandPaint.color = Color.parseColor(colors[1])
                                minuteHandPaint.color = Color.parseColor(colors[1])
                                secondHandPaint.color = Color.parseColor(colors[2])
                                hourMarkPaint.color = Color.parseColor(colors[0])
                                centerDotPaint.color = Color.parseColor(colors[0])
                                backgroundPaint.color = Color.parseColor(colors[3])

                                Log.d(TAG, "Applied color configuration from XML")
                            } catch (e: Exception) {
                                Log.e(TAG, "Failed to parse colors", e)
                            }
                        }
                    }
                }
            } catch (e: Exception) {
                Log.e(TAG, "Failed to parse color configuration", e)
            }
        }

        private fun parseSceneConfiguration(doc: Document) {
            try {
                val scenes = doc.getElementsByTagName("Scene")
                if (scenes.length > 0) {
                    val scene = scenes.item(0) as Element
                    val bgColor = scene.getAttribute("backgroundColor")

                    if (bgColor.isNotEmpty() && bgColor.contains("#")) {
                        try {
                            backgroundPaint.color = Color.parseColor(bgColor.replace("[CONFIGURATION.themeColor.3]", "#000000"))
                            Log.d(TAG, "Applied scene background color")
                        } catch (e: Exception) {
                            Log.e(TAG, "Failed to parse scene background color", e)
                        }
                    }
                }
            } catch (e: Exception) {
                Log.e(TAG, "Failed to parse scene configuration", e)
            }
        }

        private fun resetToDefaultColors() {
            hourHandPaint.color = Color.WHITE
            minuteHandPaint.color = Color.WHITE
            secondHandPaint.color = Color.RED
            hourMarkPaint.color = Color.WHITE
            centerDotPaint.color = Color.WHITE
            backgroundPaint.color = Color.BLACK
        }

        private fun drawHourMarks(canvas: Canvas, centerX: Float, centerY: Float, radius: Float) {
            val outerRadius = radius
            val innerRadius = radius * 0.9f

            for (i in 0 until 12) {
                val angle = Math.toRadians((i * 30 - 90).toDouble())
                val startX = centerX + (innerRadius * Math.cos(angle)).toFloat()
                val startY = centerY + (innerRadius * Math.sin(angle)).toFloat()
                val endX = centerX + (outerRadius * Math.cos(angle)).toFloat()
                val endY = centerY + (outerRadius * Math.sin(angle)).toFloat()

                canvas.drawLine(startX, startY, endX, endY, hourMarkPaint)
            }
        }

        private fun drawHand(
            canvas: Canvas,
            centerX: Float,
            centerY: Float,
            angle: Float,
            length: Float,
            paint: Paint
        ) {
            val angleRadians = Math.toRadians(angle.toDouble())
            val endX = centerX + (length * Math.cos(angleRadians)).toFloat()
            val endY = centerY + (length * Math.sin(angleRadians)).toFloat()

            canvas.drawLine(centerX, centerY, endX, endY, paint)
        }
    }
}

// Data class for watch face configuration
data class WatchFaceConfig(
    val width: Int,
    val height: Int,
    val backgroundColor: Int = Color.BLACK,
    val hourHandColor: Int = Color.WHITE,
    val minuteHandColor: Int = Color.WHITE,
    val secondHandColor: Int = Color.RED
)

package com.example.wear.watchface

import android.content.Context
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import java.io.File

class DefaultWatchFaceProvider(private val context: Context) {

    companion object {
        private const val DEFAULT_WATCH_FACE_ID = "com.example.wear.default"
        private const val DEFAULT_WATCH_FACE_NAME = "Default Analog"
    }

    /**
     * Create and install the default watch face if it doesn't exist
     */
    suspend fun ensureDefaultWatchFaceExists(): WatchFaceManifest {
        return withContext(Dispatchers.IO) {
            val watchFaceManager = WatchFaceManager(context)
            val existingWatchFaces = getInstalledWatchFaces()

            // Check if default watch face already exists
            val defaultWatchFace = existingWatchFaces.find { watchFace -> watchFace.id == DEFAULT_WATCH_FACE_ID }

            if (defaultWatchFace != null) {
                return@withContext defaultWatchFace
            }

            // Create default watch face
            createDefaultWatchFaceResources()
        }
    }

    private fun createDefaultWatchFaceResources(): WatchFaceManifest {
        // Create default watch face directory structure
        val defaultWatchFaceDir = File(context.filesDir, "extracted_watchfaces/$DEFAULT_WATCH_FACE_ID")
        defaultWatchFaceDir.mkdirs()

        val resourcesDir = File(defaultWatchFaceDir, "resources")
        val imagesDir = File(resourcesDir, "images")
        val fontsDir = File(resourcesDir, "fonts")

        resourcesDir.mkdirs()
        imagesDir.mkdirs()
        fontsDir.mkdirs()

        // Create manifest for default watch face
        val manifest = WatchFaceManifest(
            name = DEFAULT_WATCH_FACE_NAME,
            id = DEFAULT_WATCH_FACE_ID,
            version = "1.0.0",
            author = "System",
            description = "Default analog watch face with white hands and markers"
        )

        // Save manifest to watchface metadata
        val installedWatchFaces = getInstalledWatchFaces().toMutableList()
        installedWatchFaces.add(manifest)

        // Save updated list to shared preferences
        saveWatchFacesList(installedWatchFaces)

        return manifest
    }

    private fun getInstalledWatchFaces(): List<WatchFaceManifest> {
        val watchFaceManager = WatchFaceManager(context)
        return watchFaceManager.getInstalledWatchFaces()
    }

    private fun saveWatchFacesList(watchFaces: List<WatchFaceManifest>) {
        val sharedPrefs = context.getSharedPreferences("watch_face_prefs", Context.MODE_PRIVATE)
        val json = org.json.JSONArray().apply {
            watchFaces.forEach { watchFace ->
                put(org.json.JSONObject().apply {
                    put("name", watchFace.name)
                    put("id", watchFace.id)
                    put("version", watchFace.version)
                    put("author", watchFace.author ?: "")
                    put("description", watchFace.description ?: "")
                    put("previewImage", watchFace.previewImage ?: "")
                })
            }
        }.toString()

        sharedPrefs.edit()
            .putString("installed_watch_faces", json)
            .apply()
    }

    /**
     * Get the default watch face manifest
     */
    fun getDefaultWatchFaceManifest(): WatchFaceManifest {
        return WatchFaceManifest(
            name = DEFAULT_WATCH_FACE_NAME,
            id = DEFAULT_WATCH_FACE_ID,
            version = "1.0.0",
            author = "System",
            description = "Default analog watch face with white hands and markers"
        )
    }
}

package com.example.wear.watchface

import android.content.Context
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.util.Log
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import org.json.JSONObject
import java.io.File
import java.util.zip.ZipInputStream
import java.io.FileOutputStream
import java.io.InputStream

data class WatchFaceManifest(
    val name: String,
    val id: String,
    val version: String,
    val author: String? = null,
    val description: String? = null,
    val previewImage: String? = null
)

data class WatchFaceResources(
    val manifest: WatchFaceManifest,
    val previewBitmap: Bitmap? = null,
    val watchfaceXml: String? = null,
    val resourcesDir: File,
    val imagesDir: File,
    val fontsDir: File
)

class WatchFaceParser {

    companion object {
        private const val TAG = "WatchFaceParser"
        private const val MANIFEST_FILE = "manifest.json"
        private const val PREVIEW_FILE = "preview.png"
        private const val WATCHFACE_XML = "watchface.xml"
        private const val RESOURCES_DIR = "resources"
        private const val IMAGES_DIR = "images"
        private const val FONTS_DIR = "fonts"
    }

    suspend fun parseWatchFaceFile(context: Context, wffFile: File): WatchFaceResources? {
        return withContext(Dispatchers.IO) {
            try {
                Log.d(TAG, "Starting to parse watch face file: ${wffFile.name}")

                // Create extraction directory
                val extractDir = File(context.filesDir, "extracted_watchfaces/${wffFile.nameWithoutExtension}")
                if (extractDir.exists()) {
                    extractDir.deleteRecursively()
                }
                extractDir.mkdirs()

                // Extract ZIP file
                val extractedFiles = extractZipFile(wffFile, extractDir)
                Log.d(TAG, "Extracted ${extractedFiles.size} files")

                // Parse manifest.json
                val manifestFile = File(extractDir, MANIFEST_FILE)
                if (!manifestFile.exists()) {
                    Log.e(TAG, "manifest.json not found in watch face file")
                    return@withContext null
                }

                val manifest = parseManifest(manifestFile)
                Log.d(TAG, "Parsed manifest: ${manifest.name} v${manifest.version}")

                // Load preview image
                val previewFile = File(extractDir, PREVIEW_FILE)
                val previewBitmap = if (previewFile.exists()) {
                    BitmapFactory.decodeFile(previewFile.absolutePath)
                } else {
                    Log.w(TAG, "Preview image not found")
                    null
                }

                // Read watchface.xml
                val watchfaceXmlFile = File(extractDir, WATCHFACE_XML)
                val watchfaceXml = if (watchfaceXmlFile.exists()) {
                    watchfaceXmlFile.readText()
                } else {
                    Log.w(TAG, "watchface.xml not found")
                    null
                }

                // Setup resource directories
                val resourcesDir = File(extractDir, RESOURCES_DIR)
                val imagesDir = File(resourcesDir, IMAGES_DIR)
                val fontsDir = File(resourcesDir, FONTS_DIR)

                // Create directories if they don't exist
                resourcesDir.mkdirs()
                imagesDir.mkdirs()
                fontsDir.mkdirs()

                Log.d(TAG, "Successfully parsed watch face: ${manifest.name}")

                WatchFaceResources(
                    manifest = manifest,
                    previewBitmap = previewBitmap,
                    watchfaceXml = watchfaceXml,
                    resourcesDir = resourcesDir,
                    imagesDir = imagesDir,
                    fontsDir = fontsDir
                )

            } catch (e: Exception) {
                Log.e(TAG, "Failed to parse watch face file", e)
                null
            }
        }
    }

    private fun extractZipFile(zipFile: File, extractDir: File): List<String> {
        val extractedFiles = mutableListOf<String>()

        ZipInputStream(zipFile.inputStream()).use { zipInputStream ->
            var entry = zipInputStream.nextEntry

            while (entry != null) {
                val entryFile = File(extractDir, entry.name)

                if (entry.isDirectory) {
                    entryFile.mkdirs()
                } else {
                    // Create parent directories if needed
                    entryFile.parentFile?.mkdirs()

                    // Extract file
                    FileOutputStream(entryFile).use { outputStream ->
                        zipInputStream.copyTo(outputStream)
                    }

                    extractedFiles.add(entry.name)
                    Log.d(TAG, "Extracted: ${entry.name}")
                }

                zipInputStream.closeEntry()
                entry = zipInputStream.nextEntry
            }
        }

        return extractedFiles
    }

    private fun parseManifest(manifestFile: File): WatchFaceManifest {
        val jsonString = manifestFile.readText()
        val jsonObject = JSONObject(jsonString)

        return WatchFaceManifest(
            name = jsonObject.getString("name"),
            id = jsonObject.getString("id"),
            version = jsonObject.getString("version"),
            author = jsonObject.optString("author", null),
            description = jsonObject.optString("description", null),
            previewImage = jsonObject.optString("previewImage", null)
        )
    }
}

package com.example.wear.watchface

import android.content.Context
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.util.Log
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import org.json.JSONObject
import java.io.File
import java.util.zip.ZipInputStream
import java.io.FileOutputStream
import java.io.InputStream

data class WatchFaceManifest(
    val name: String,
    val id: String,
    val version: String,
    val author: String? = null,
    val description: String? = null,
    val previewImage: String? = null
)

data class WatchFaceResources(
    val manifest: WatchFaceManifest,
    val previewBitmap: Bitmap? = null,
    val watchfaceXml: String? = null,
    val resourcesDir: File,
    val imagesDir: File,
    val fontsDir: File
)

class WatchFaceParser {

    companion object {
        private const val TAG = "WatchFaceParser"
        private const val MANIFEST_FILE = "manifest.json"
        private const val PREVIEW_FILE = "preview.png"
        private const val WATCHFACE_XML = "watchface.xml"
        private const val RESOURCES_DIR = "resources"
        private const val IMAGES_DIR = "images"
        private const val FONTS_DIR = "fonts"
    }

    suspend fun parseWatchFaceFile(context: Context, wffFile: File): WatchFaceResources? {
        return withContext(Dispatchers.IO) {
            try {
                Log.d(TAG, "Starting to parse watch face file: ${wffFile.name}")

                // Create extraction directory
                val extractDir = File(context.filesDir, "extracted_watchfaces/${wffFile.nameWithoutExtension}")
                if (extractDir.exists()) {
                    extractDir.deleteRecursively()
                }
                extractDir.mkdirs()

                // Extract ZIP file
                val extractedFiles = extractZipFile(wffFile, extractDir)
                Log.d(TAG, "Extracted ${extractedFiles.size} files")

                // Find the actual location of manifest.json
                // It could be in root directory or in a subdirectory like "watchface/"
                val manifestFile = findFile(extractDir, MANIFEST_FILE)
                if (manifestFile == null || !manifestFile.exists()) {
                    Log.e(TAG, "manifest.json not found in watch face file")
                    Log.d(TAG, "Extracted files: ${extractedFiles.joinToString(", ")}")
                    return@withContext null
                }

                val manifest = parseManifest(manifestFile)
                Log.d(TAG, "Parsed manifest: ${manifest.name} v${manifest.version}")

                // Find preview image in the same directory as manifest
                val manifestDir = manifestFile.parentFile!!
                val previewFile = File(manifestDir, PREVIEW_FILE)
                val previewBitmap = if (previewFile.exists()) {
                    BitmapFactory.decodeFile(previewFile.absolutePath)
                } else {
                    // Try to find preview.png anywhere in the extracted files
                    val foundPreview = findFile(extractDir, PREVIEW_FILE)
                    if (foundPreview?.exists() == true) {
                        BitmapFactory.decodeFile(foundPreview.absolutePath)
                    } else {
                        Log.w(TAG, "Preview image not found")
                        null
                    }
                }

                // Find watchface.xml in the same directory as manifest
                val watchfaceXmlFile = File(manifestDir, WATCHFACE_XML)
                val watchfaceXml = if (watchfaceXmlFile.exists()) {
                    watchfaceXmlFile.readText()
                } else {
                    // Try to find watchface.xml anywhere in the extracted files
                    val foundXml = findFile(extractDir, WATCHFACE_XML)
                    if (foundXml?.exists() == true) {
                        foundXml.readText()
                    } else {
                        Log.w(TAG, "watchface.xml not found")
                        null
                    }
                }

                // Setup resource directories - look for resources in the same directory as manifest
                val resourcesDir = File(manifestDir, RESOURCES_DIR)
                val imagesDir = File(resourcesDir, IMAGES_DIR)
                val fontsDir = File(resourcesDir, FONTS_DIR)

                // If resources not found in manifest directory, try to find it anywhere
                val actualResourcesDir = if (resourcesDir.exists()) {
                    resourcesDir
                } else {
                    findDirectory(extractDir, RESOURCES_DIR) ?: resourcesDir
                }

                val actualImagesDir = File(actualResourcesDir, IMAGES_DIR)
                val actualFontsDir = File(actualResourcesDir, FONTS_DIR)

                // Create directories if they don't exist
                actualResourcesDir.mkdirs()
                actualImagesDir.mkdirs()
                actualFontsDir.mkdirs()

                Log.d(TAG, "Successfully parsed watch face: ${manifest.name}")
                Log.d(TAG, "Manifest found at: ${manifestFile.absolutePath}")
                Log.d(TAG, "Resources directory: ${actualResourcesDir.absolutePath}")

                WatchFaceResources(
                    manifest = manifest,
                    previewBitmap = previewBitmap,
                    watchfaceXml = watchfaceXml,
                    resourcesDir = resourcesDir,
                    imagesDir = imagesDir,
                    fontsDir = fontsDir
                )

            } catch (e: Exception) {
                Log.e(TAG, "Failed to parse watch face file", e)
                null
            }
        }
    }

    private fun extractZipFile(zipFile: File, extractDir: File): List<String> {
        val extractedFiles = mutableListOf<String>()

        ZipInputStream(zipFile.inputStream()).use { zipInputStream ->
            var entry = zipInputStream.nextEntry

            while (entry != null) {
                val entryFile = File(extractDir, entry.name)

                if (entry.isDirectory) {
                    entryFile.mkdirs()
                } else {
                    // Create parent directories if needed
                    entryFile.parentFile?.mkdirs()

                    // Extract file
                    FileOutputStream(entryFile).use { outputStream ->
                        zipInputStream.copyTo(outputStream)
                    }

                    extractedFiles.add(entry.name)
                    Log.d(TAG, "Extracted: ${entry.name}")
                }

                zipInputStream.closeEntry()
                entry = zipInputStream.nextEntry
            }
        }

        return extractedFiles
    }

    private fun parseManifest(manifestFile: File): WatchFaceManifest {
        val jsonString = manifestFile.readText()
        val jsonObject = JSONObject(jsonString)

        return WatchFaceManifest(
            name = jsonObject.getString("name"),
            id = jsonObject.getString("id"),
            version = jsonObject.getString("version"),
            author = jsonObject.optString("author", null),
            description = jsonObject.optString("description", null),
            previewImage = jsonObject.optString("previewImage", null)
        )
    }

    // Helper function to find a file recursively in a directory
    private fun findFile(directory: File, fileName: String): File? {
        if (!directory.exists() || !directory.isDirectory) return null

        // Check if file exists in current directory
        val directFile = File(directory, fileName)
        if (directFile.exists()) {
            return directFile
        }

        // Search in subdirectories
        directory.listFiles()?.forEach { file ->
            if (file.isDirectory) {
                val found = findFile(file, fileName)
                if (found != null) return found
            }
        }

        return null
    }

    // Helper function to find a directory recursively
    private fun findDirectory(directory: File, dirName: String): File? {
        if (!directory.exists() || !directory.isDirectory) return null

        directory.listFiles()?.forEach { file ->
            if (file.isDirectory) {
                if (file.name == dirName) {
                    return file
                }
                val found = findDirectory(file, dirName)
                if (found != null) return found
            }
        }

        return null
    }
}
